  if (pathname.startsWith("/demo/") || pathname.startsWith("/demo-assets/") || pathname.startsWith("/api/v1/demo/")) return true;
  if (pathname.startsWith("/w/") || pathname.startsWith("/api/v1/w/")) return true;
