  if (conversationId) await req(env, "DELETE", "/conversations/" + conversationId, null, "2021-04-15");
  await req(env, "POST", "/contacts/" + contactId + "/tags", { tags: ["blocked-sender"] }, "2021-07-28").catch(() => {});
