const sphere=ctx.createRadialGradient(cx-R*.32,cy-R*.32,R*.03,cx,cy,R*pulse);sphere.addColorStop(0,'#b8eaffaa');sphere.addColorStop(.18,'#38a7ff9c');sphere.addColorStop(.45,'#156dbf99');sphere.addColorStop(.78,'#083057b0');sphere.addColorStop(.96,'#0b4c8580');sphere.addColorStop(1,'#79c9ff45');// Solid sphere volume is rendered by the visible CSS layer.
