for(let band=0;band<4;band++){ctx.strokeStyle=band%2?'#79c9ff50':'#38a7ff65';ctx.lineWidth=.9;ctx.beginPath();for(let i=0;i<=140;i++){const x=-R+i/140*R*2,y=Math.sin(i/140*Math.PI*4+phase*1.8+band*.55)*R*.08+Math.sin(i/140*Math.PI)*R*(band-.9)*.13;i?ctx.lineTo(cx+x,cy+y):ctx.moveTo(cx+x,cy+y);}ctx.stroke();}
