ctx.strokeStyle='#79c9ff65';ctx.lineWidth=1;ctx.beginPath();ctx.arc(cx,cy,R*pulse,0,Math.PI*2);ctx.stroke();
for(let i=0;i<100;i++){const a=i/100*Math.PI*2+phase*.06,r=R*1.36;ctx.strokeStyle=i%5===0?'#79c9ffaa':'#238de848';ctx.lineWidth=i%5===0?1.2:.7;ctx.beginPath();ctx.moveTo(cx+Math.cos(a)*r,cy+Math.sin(a)*r);ctx.lineTo(cx+Math.cos(a)*(r+(i%5===0?10:4)),cy+Math.sin(a)*(r+(i%5===0?10:4)));ctx.stroke();}
